INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Ethernet eine drahtlose Technologie?', 2, '[{"text": "No", "correct": true, "because": "Cable-based"}, {"text": "Yes", "correct": false, "because": "Wired, not wireless"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt Ethernet?', 3, '[{"text": "Datenübertragung in Netzwerken", "correct": true, "because": "LAN connectivity"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Security not primary"}, {"text": "Hardware optimieren", "correct": false, "because": "Network focus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten sind für Ethernet typisch?', 5, '[{"text": "Switches", "correct": true, "because": "Data distribution"}, {"text": "Twisted-Pair cables", "correct": true, "because": "Physical medium"}, {"text": "Paper logs", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Are these statements correct? a) Ethernet uses the IEEE 802.3 standard. b) It’s only for WANs.', 3, '[{"text": "Only a) is correct", "correct": true, "because": "LAN focus"}, {"text": "Both are correct", "correct": false, "because": "b) is false"}, {"text": "Only b) is correct", "correct": false, "because": "a) is true"}, {"text": "Both are false", "correct": false, "because": "a) is true"}]'),
('00000000-0000-0000-0000-000000000000', 'What do I ignore in Ethernet?', 4, '[{"text": "Cabling standards", "correct": false, "because": "Critical for setup"}, {"text": "Data rates", "correct": false, "because": "Defines performance"}, {"text": "Paper size", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Can you recall if Ethernet always uses fiber optic cables?', 2, '[{"text": "No", "correct": true, "because": "Also copper"}, {"text": "Yes", "correct": false, "because": "Not exclusive"}]'),
('00000000-0000-0000-0000-000000000000', 'Which standard defines Ethernet?', 3, '[{"text": "IEEE 802.3", "correct": true, "because": "Ethernet standard"}, {"text": "IEEE 802.11", "correct": false, "because": "Wi-Fi"}, {"text": "ISO 9001", "correct": false, "because": "Quality management"}]'),
('00000000-0000-0000-0000-000000000000', 'What benefits does Ethernet offer?', 5, '[{"text": "High reliability", "correct": true, "because": "Stable connection"}, {"text": "Scalability", "correct": true, "because": "Supports growth"}, {"text": "Paper savings", "correct": false, "because": "Not applicable"}]'),
('00000000-0000-0000-0000-000000000000', 'I’ve heard: a) Ethernet supports high-speed data transfer. b) It’s only for small networks. Is that true?', 3, '[{"text": "Only a) is correct", "correct": true, "because": "Scales to large networks"}, {"text": "Both are correct", "correct": false, "because": "b) is false"}, {"text": "Only b) is correct", "correct": false, "because": "a) is true"}, {"text": "Both are false", "correct": false, "because": "a) is true"}]'),
('00000000-0000-0000-0000-000000000000', 'What don’t I need for Ethernet?', 4, '[{"text": "Ethernet cables", "correct": false, "because": "Physical medium"}, {"text": "Switches", "correct": false, "because": "Network connectivity"}, {"text": "Wireless routers", "correct": true, "because": "Wired focus"}]'),
('00000000-0000-0000-0000-000000000000', 'How was it again? Does Ethernet use the CSMA/CD method in modern networks?', 2, '[{"text": "No", "correct": true, "because": "Switched networks reduce collisions"}, {"text": "Yes", "correct": false, "because": "Legacy method"}]'),
('00000000-0000-0000-0000-000000000000', 'Which cable types are used in Ethernet?', 4, '[{"text": "Cat5e", "correct": true, "because": "Common standard"}, {"text": "Fiber optic", "correct": true, "because": "High-speed option"}, {"text": "Paper strips", "correct": false, "because": "Not a medium"}]'),
('00000000-0000-0000-0000-000000000000', 'I’ve heard that Ethernet is only for LANs. Is that true?', 2, '[{"text": "No", "correct": true, "because": "Also MANs"}, {"text": "Yes", "correct": false, "because": "Wider use"}]'),
('00000000-0000-0000-0000-000000000000', 'What do I prioritize in Ethernet?', 3, '[{"text": "Reliability", "correct": true, "because": "Stable connection"}, {"text": "Paper documentation", "correct": false, "because": "Irrelevant"}, {"text": "Speed alone", "correct": false, "because": "Balance needed"}]'),
('00000000-0000-0000-0000-000000000000', 'Are these statements correct? a) Ethernet supports multiple speeds. b) It’s wireless by default.', 3, '[{"text": "Only a) is correct", "correct": true, "because": "Wired technology"}, {"text": "Both are correct", "correct": false, "because": "b) is false"}, {"text": "Only b) is correct", "correct": false, "because": "a) is true"}, {"text": "Both are false", "correct": false, "because": "a) is true"}]'),
('00000000-0000-0000-0000-000000000000', 'What technologies enhance Ethernet?', 5, '[{"text": "PoE", "correct": true, "because": "Power over Ethernet"}, {"text": "VLANs", "correct": true, "because": "Virtual LANs"}, {"text": "Paper protocols", "correct": false, "because": "Not applicable"}]'),
('00000000-0000-0000-0000-000000000000', 'What’s unimportant for Ethernet?', 3, '[{"text": "Data rate", "correct": false, "because": "Performance factor"}, {"text": "Cable type", "correct": false, "because": "Standards matter"}, {"text": "Font style", "correct": true, "because": "No impact"}]'),
('00000000-0000-0000-0000-000000000000', 'How was it again? Can Ethernet support gigabit speeds?', 3, '[{"text": "Yes", "correct": true, "because": "Gigabit Ethernet"}, {"text": "No", "correct": false, "because": "Widely supported"}]'),
('00000000-0000-0000-0000-000000000000', 'Can you recall if Ethernet is limited to short distances?', 2, '[{"text": "No", "correct": true, "because": "Fiber extends range"}, {"text": "Yes", "correct": false, "because": "Varies by medium"}]'),
('00000000-0000-0000-0000-000000000000', 'What’s central to Ethernet?', 4, '[{"text": "Wired connectivity", "correct": true, "because": "Core principle"}, {"text": "Wireless signals", "correct": false, "because": "Not Ethernet"}, {"text": "Paper records", "correct": false, "because": "Irrelevant"}]');
